package cn.workbench;

import org.springframework.web.bind.annotation.*;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import static cn.workbench.Records.map;

@RestController @RequestMapping("/api/v1/organization")
public class OrganizationChangesController {
 final OrganizationChanges changes;final Store db;final Records r;final Policy p;final Writes w;
 public OrganizationChangesController(OrganizationChanges changes,Store db,Records r,Policy p,Writes w){this.changes=changes;this.db=db;this.r=r;this.p=p;this.w=w;}
 void adminTarget(Policy.Actor actor,long uid){p.admin(actor);var rows=changes.query("SELECT * FROM user_scope WHERE user_id=?",uid);if(rows.isEmpty()||actor.company()!=null&&rows.stream().anyMatch(s->s.get("companyId")==null||!Objects.equals(actor.company(),Jsons.integer(s.get("companyId")))||"GROUP_LEADER".equals(s.get("role"))))throw ApiException.denied();}
 @GetMapping("/appointments") Object appointments(HttpServletRequest q,@RequestParam(required=false)Long userId){var actor=p.actor(q);p.admin(actor);if(userId!=null)adminTarget(actor,userId);var rows=changes.query("SELECT s.*,u.name AS user_name FROM user_scope s JOIN app_user u ON u.id=s.user_id"+(userId==null?"":" WHERE s.user_id=?")+" ORDER BY s.id",userId==null?new Object[]{}:new Object[]{userId});return Api.ok(map("items",rows.stream().filter(s->actor.company()==null||Objects.equals(actor.company(),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))).map(s->{var out=new LinkedHashMap<>(s);boolean permitted=actor.company()==null||changes.query("SELECT * FROM user_scope WHERE user_id=?",s.get("userId")).stream().allMatch(scope->scope.get("companyId")!=null&&Objects.equals(actor.company(),Jsons.integer(scope.get("companyId")))&&!"GROUP_LEADER".equals(scope.get("role")));out.put("allowedActions",permitted?List.of("edit"):List.of());return out;}).toList()));}
 @PutMapping("/appointments/{id}") Object appointment(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var actor=p.actor(q);p.admin(actor);p.freshTotp(q);return w.run(q,b,()->{var row=changes.query("SELECT * FROM user_scope WHERE id=? FOR UPDATE",id).stream().findFirst().orElseThrow(ApiException::denied);long uid=TaskService.number(row,"userId");adminTarget(actor,uid);TaskService.version(row,b);String status=TaskService.text(b,"employmentStatus",20),type=TaskService.text(b,"appointmentType",20),reason=TaskService.text(b,"reason",1000);if(!Set.of("ACTIVE","ON_LEAVE","LEFT").contains(status)||!Set.of("PRIMARY","CONCURRENT").contains(type))throw TaskService.invalid("Invalid employment status or appointment type");Instant from=nullableInstant(b.get("validFrom")),until=nullableInstant(b.get("validUntil"));if(from!=null&&until!=null&&!until.isAfter(from))throw TaskService.invalid("Appointment end must follow start");boolean enabled=!status.equals("LEFT")&&Boolean.TRUE.equals(b.get("enabled"));int changed=changes.jdbc.update("UPDATE user_scope SET valid_from=?,valid_until=?,employment_status=?,appointment_type=?,enabled=?,version=version+1 WHERE id=? AND version=?",stamp(from),stamp(until),status,type,enabled,id,row.get("version"));if(changed!=1)throw ApiException.conflict();changes.jdbc.update("UPDATE app_user SET session_version=session_version+1 WHERE id=?",uid);r.create("APPOINTMENT_CHANGE",row.get("companyId")==null?0:Jsons.integer(row.get("companyId")),row.get("deptId")==null?null:Jsons.integer(row.get("deptId")),null,actor.uid(),"RECORDED",map("scopeId",id,"userId",uid,"previous",row,"employmentStatus",status,"appointmentType",type,"validFrom",from==null?null:from.toString(),"validUntil",until==null?null:until.toString(),"enabled",enabled,"reason",reason,"actorId",actor.uid()));w.audit(actor,"APPOINTMENT_CHANGE",id);return changes.query("SELECT * FROM user_scope WHERE id=?",id).getFirst();});}
 static Instant nullableInstant(Object value){if(value==null||"".equals(value))return null;try{return Records.instant(value);}catch(Exception e){throw TaskService.invalid("Use an ISO8601 timestamp");}}static Timestamp stamp(Instant value){return value==null?null:Timestamp.from(value);}
 @GetMapping("/delegations") Object delegations(HttpServletRequest q){var actor=p.actor(q);var rows=changes.query("SELECT d.*,u.name AS delegator_name,v.name AS delegate_name FROM scope_delegation d JOIN app_user u ON u.id=d.delegator_id JOIN app_user v ON v.id=d.delegate_user_id WHERE (d.delegator_id=? OR d.delegate_user_id=?) AND d.company_id=? AND d.dept_id=? ORDER BY d.id DESC",actor.uid(),actor.uid(),actor.company(),actor.dept());return Api.ok(map("allowedActions",actor.departmentHead()&&actor.delegationId()==null?List.of("create"):List.of(),"items",rows.stream().map(d->{var view=new LinkedHashMap<>(d);view.remove("permissionsJson");view.put("permissions",changes.permissions(d));List<String> actions=new ArrayList<>();if(actor.delegationId()==null){if(TaskService.number(d,"delegateUserId")==actor.uid()&&changes.effective(d)&&Objects.equals(actor.company(),Jsons.integer(d.get("companyId")))&&Objects.equals(actor.dept(),Jsons.integer(d.get("deptId"))))actions.add("activate");if(TaskService.number(d,"delegatorId")==actor.uid()&&"ACTIVE".equals(d.get("status")))actions.add("revoke");}view.put("allowedActions",actions);view.put("effective",changes.effective(d));return view;}).toList()));}
 @PostMapping("/delegations") Object delegate(@RequestBody Map<String,Object>b,HttpServletRequest q){var actor=p.actor(q);if(!actor.departmentHead()||actor.delegationId()!=null)throw ApiException.denied();p.freshTotp(q);return w.run(q,b,()->{long user=TaskService.number(b,"delegateUserId");if(user==actor.uid()||!changes.member(user,actor.company(),actor.dept()))throw ApiException.denied();Object permissionInput=b.get("permissions");if(!(permissionInput instanceof List<?> list)||list.isEmpty()||list.size()>OrganizationChanges.PERMISSIONS.size())throw TaskService.invalid("Choose explicit task permissions");Set<String> permissions=new TreeSet<>();for(var permission:list){String value=String.valueOf(permission);if(!OrganizationChanges.PERMISSIONS.contains(value)||!permissions.add(value))throw TaskService.invalid("Invalid or duplicate delegation permission");}Instant from=nullableInstant(b.get("validFrom")),until=nullableInstant(b.get("validUntil"));if(from==null||until==null||!until.isAfter(from)||!until.isAfter(Instant.now())||Duration.between(from,until).compareTo(Duration.ofDays(31))>0)throw TaskService.invalid("Delegation requires a future end and a window up to31 days");String reason=TaskService.text(b,"reason",1000);var key=new org.springframework.jdbc.support.GeneratedKeyHolder();changes.jdbc.update(connection->{var statement=connection.prepareStatement("INSERT INTO scope_delegation(delegator_id,delegate_user_id,source_scope_id,company_id,dept_id,permissions_json,valid_from,valid_until,reason) VALUES(?,?,?,?,?,?,?,?,?)",new String[]{"id"});Object[] values={actor.uid(),user,actor.scopeId(),actor.company(),actor.dept(),changes.json.write(permissions),stamp(from),stamp(until),reason};for(int i=0;i<values.length;i++)statement.setObject(i+1,values[i]);return statement;},key);long id=Objects.requireNonNull(key.getKey()).longValue();w.audit(actor,"DELEGATION_CREATE",id);var view=changes.delegation(id,false);view.remove("permissionsJson");view.put("permissions",permissions);return view;});}
 @PostMapping("/delegations/{id}/revoke") Object revoke(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest q){var actor=p.actor(q);if(actor.delegationId()!=null)throw ApiException.denied();p.freshTotp(q);return w.run(q,b,()->{var d=changes.delegation(id,true);if(TaskService.number(d,"delegatorId")!=actor.uid())throw ApiException.denied();TaskService.version(d,b);if(!"ACTIVE".equals(d.get("status")))throw ApiException.conflict();String reason=TaskService.text(b,"reason",1000);changes.jdbc.update("UPDATE scope_delegation SET status='REVOKED',revocation_reason=?,revoked_by=?,revoked_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=?",reason,actor.uid(),id);w.audit(actor,"DELEGATION_REVOKE",id);return map("id",id,"status","REVOKED","version",TaskService.integer(d,"version")+1);});}
 @PostMapping("/delegations/{id}/activate") Object activate(@PathVariable long id,HttpServletRequest q){var actor=p.actor(q);if(actor.delegationId()!=null)throw ApiException.denied();p.freshTotp(q);var d=changes.delegation(id,false);if(TaskService.number(d,"delegateUserId")!=actor.uid()||!changes.effective(d)||!Objects.equals(actor.company(),Jsons.integer(d.get("companyId")))||!Objects.equals(actor.dept(),Jsons.integer(d.get("deptId"))))throw ApiException.denied();w.audit(actor,"DELEGATION_ACTIVATE",id);q.getSession().setAttribute("delegationId",id);return Api.ok(map("delegationId",id));}
 @PostMapping("/delegations/leave") Object leave(HttpServletRequest q){long uid=Auth.uid(q);Object id=q.getSession().getAttribute("delegationId");q.getSession().removeAttribute("delegationId");if(id!=null){Object scope=q.getSession().getAttribute("scopeId");var s=scope==null?null:db.scope(uid,Jsons.number(scope));if(s!=null)w.audit(new Policy.Actor(uid,(String)s.get("role"),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")),s.get("deptId")==null?null:Jsons.integer(s.get("deptId")),Jsons.number(scope)),"DELEGATION_LEAVE",Jsons.number(id));}return Api.ok(Map.of());}
 boolean transferAllowed(Policy.Actor actor,Map<String,Object>sub){return actor.delegationId()==null&&!actor.administrator()&&(actor.leader()&&Domain.companyAllowed(actor.role(),actor.company(),TaskService.integer(sub,"companyId"))||actor.departmentHead()&&Objects.equals(actor.company(),TaskService.integer(sub,"companyId"))&&Objects.equals(actor.dept(),TaskService.integer(sub,"deptId")));}
 @GetMapping("/handover-tasks") Object candidates(HttpServletRequest q){var actor=p.actor(q);if(!actor.leader()&&!actor.departmentHead())throw ApiException.denied();return Api.ok(map("items",r.list("SUB_TASK",actor.company(),actor.leader()?null:actor.dept()).stream().filter(s->transferAllowed(actor,s)&&Set.of("IN_PROGRESS","REWORK").contains(s.get("status"))&&!Set.of("COMPLETED","CANCELLED").contains(r.get(TaskService.number(s,"taskId")).get("status"))).map(s->{var view=new LinkedHashMap<>(s);view.put("taskTitle",r.get(TaskService.number(s,"taskId")).get("title"));view.put("currentOwnerId",s.get("ownerId"));view.put("allowedActions",List.of("transfer"));return view;}).toList()));}
 @PostMapping("/handovers") Object handover(@RequestBody Map<String,Object>b,HttpServletRequest q){var actor=p.actor(q);if(!actor.leader()&&!actor.departmentHead()||actor.delegationId()!=null)throw ApiException.denied();p.freshTotp(q);return w.run(q,b,()->{String reason=TaskService.text(b,"reason",1000);if(!(b.get("items") instanceof List<?> inputs)||inputs.isEmpty()||inputs.size()>100)throw TaskService.invalid("Transfer1 to100 tasks per batch");var rows=new ArrayList<Map<String,Object>>();Set<Long> unique=new HashSet<>();for(Object input:inputs){if(!(input instanceof Map<?,?> raw))throw TaskService.invalid("Invalid transfer item");var item=new LinkedHashMap<String,Object>();raw.forEach((k,v)->item.put(String.valueOf(k),v));long id=TaskService.number(item,"subTaskId");if(!unique.add(id))throw TaskService.invalid("Duplicate transfer task");var s=r.get(id);if(!"SUB_TASK".equals(s.get("kind"))||!transferAllowed(actor,s))throw ApiException.denied();item.put("taskId",s.get("taskId"));rows.add(item);}rows.sort(Comparator.comparingLong(x->TaskService.number(x,"taskId")));for(var item:rows)r.lock(TaskService.number(item,"taskId"));var result=new ArrayList<Map<String,Object>>();for(var item:rows){var sub=r.lock(TaskService.number(item,"subTaskId"));var task=r.get(TaskService.number(sub,"taskId"));if(!transferAllowed(actor,sub))throw ApiException.denied();TaskService.version(sub,item);if(!Set.of("IN_PROGRESS","REWORK").contains(sub.get("status"))||Set.of("DRAFT","PENDING_ACCEPTANCE","PENDING_ACCEPTANCE_WITH_GAP","COMPLETED","CANCELLED").contains(task.get("status")))throw ApiException.conflict();changes.apply(actor,sub,TaskService.number(item,"userId"),reason);r.save(sub);result.add(sub);}return map("items",result);});}
 @GetMapping("/handovers") Object history(HttpServletRequest q){var actor=p.actor(q);if(!actor.leader()&&!actor.departmentHead()||actor.delegationId()!=null)throw ApiException.denied();String sql="SELECT * FROM task_handover";List<Object> params=new ArrayList<>();if(actor.company()!=null){sql+=" WHERE company_id=?";params.add(actor.company());if(!actor.leader()){sql+=" AND dept_id=?";params.add(actor.dept());}}return Api.ok(map("items",changes.query(sql+" ORDER BY id DESC LIMIT 1000",params.toArray())));}
}
